// Generated by scripts/build-glossary-data.mjs from content-source/glossary. Do not edit by hand.
export const GLOSSARY_SHARD = Object.freeze({"blockchain":{"slug":"blockchain","cat":"basics","en":"Blockchain","contentLocale":"id","term":"Blockchain","aka":["rantai blok"],"short":"Blockchain adalah buku besar digital yang disimpan bersama oleh banyak komputer, di mana transaksi dikelompokkan ke dalam blok yang saling terhubung sehingga sangat sulit diubah setelah dicatat.","body":["Setiap blok berisi kumpulan transaksi, waktu pencatatan, dan sidik digital (hash) dari blok sebelumnya. Karena setiap blok merujuk ke blok sebelumnya, terbentuklah rantai. Jika seseorang mencoba mengubah satu transaksi lama, hash blok itu ikut berubah dan seluruh rantai sesudahnya menjadi tidak cocok, sehingga jaringan langsung menolaknya.",["Salinan buku besar ini disimpan oleh ribuan ",["node","node"]," di seluruh dunia. Untuk menyepakati blok mana yang sah, jaringan memakai mekanisme konsensus, misalnya ",["proof of work","proof-of-work"]," pada ",["Bitcoin","bitcoin"]," atau ",["proof of stake","proof-of-stake"]," pada ",["Ethereum","ethereum"],". Tidak ada satu pihak pun yang bisa diam-diam menghapus saldo Anda."],["Bagi trader, blockchain penting karena setiap deposit dan penarikan kripto benar-benar terjadi di jaringan tertentu. Anda harus memilih jaringan yang sama di sisi pengirim dan penerima, dan Anda bisa memeriksa status transaksi lewat ",["block explorer","block-explorer"],"."]],"example":"Misalkan Anda mengirim 50 USDT dari exchange ke dompet pribadi lewat jaringan TRON. Transaksi masuk ke antrean, lalu dimasukkan ke dalam blok oleh jaringan dalam hitungan detik. Exchange biasanya menunggu sejumlah konfirmasi, misalnya 20 blok, sebelum dana dianggap final. Setelah itu, siapa pun bisa melihat transaksi tersebut di block explorer beserta hash-nya, jumlah 50 USDT, dan alamat tujuan, tetapi tidak ada yang bisa mengubah angkanya.","mistakes":["Menganggap semua blockchain sama, padahal USDT di jaringan Ethereum dan USDT di jaringan TRON memakai alamat dan biaya yang berbeda.","Mengira transaksi yang sudah terkonfirmasi bisa dibatalkan seperti transfer bank.","Percaya bahwa blockchain membuat sebuah proyek otomatis aman, padahal kode, tim, dan tokennya tetap bisa bermasalah."],"faq":[{"q":"Apakah blockchain sama dengan Bitcoin?","a":"Tidak. Bitcoin adalah aset kripto yang berjalan di atas blockchain miliknya sendiri. Blockchain adalah teknologinya, dan ada banyak blockchain lain seperti Ethereum, Solana, atau BNB Chain."},{"q":"Apakah data di blockchain bisa dihapus?","a":"Pada blockchain publik, transaksi yang sudah final praktis tidak bisa dihapus atau diubah. Itulah sebabnya salah kirim alamat biasanya tidak bisa ditarik kembali."}],"title":"Apa itu blockchain? Arti dan cara kerjanya","description":"Pelajari arti blockchain, cara blok saling terhubung, dan kenapa jaringan yang Anda pilih penting saat deposit atau tarik kripto.","related":[["cryptocurrency","Cryptocurrency (aset kripto)","Cryptocurrency atau aset kripto adalah aset digital yang dicatat di blockchain dan diamankan dengan kriptografi, sehingga bisa dikirim antarpengguna tanpa bank sebagai perantara."],["proof-of-work","Proof of work (PoW)","Proof of work (PoW) adalah mekanisme konsensus di mana penambang bersaing memecahkan teka-teki komputasi agar berhak menambahkan blok baru dan menerima imbalan."],["proof-of-stake","Proof of stake (PoS)","Proof of stake (PoS) adalah mekanisme konsensus di mana validator mengunci koin sebagai jaminan untuk berhak memvalidasi blok, lalu mendapat imbalan atau kena penalti sesuai perilakunya."],["smart-contract","Smart contract","Smart contract adalah program yang disimpan dan dijalankan di blockchain, yang otomatis mengeksekusi aturan tertentu ketika syaratnya terpenuhi, tanpa perlu perantara."],["block-explorer","Block explorer","Block explorer adalah situs atau aplikasi untuk mencari dan melihat data blockchain secara publik, seperti status transaksi, saldo alamat, isi blok, dan jumlah konfirmasi."]],"lesson":{"id":"E03","slug":"exchange-vs-wallet","ep":3,"title":"Di mana koin saya? Bursa vs dompet"},"coin":{"slug":"bitcoin","name":"Bitcoin","symbol":"BTC"},"tool":null,"cta":false},"trading-volume":{"slug":"trading-volume","cat":"trading","en":"Trading volume","contentLocale":"id","term":"Volume trading (trading volume)","aka":["volume perdagangan","volume 24 jam","trading volume"],"short":"Volume trading adalah total nilai atau jumlah aset yang diperdagangkan dalam periode tertentu, misalnya 24 jam, dan dipakai untuk mengukur seberapa aktif sebuah pasar.","body":[["Volume biasanya ditampilkan dalam dua bentuk: jumlah koin (misalnya 1.500 ",["BTC","bitcoin"],") atau nilai dalam mata uang kutipan (misalnya 90 juta ",["USDT","usdt"],"). Di ",["grafik candlestick","candlestick-chart"],", volume muncul sebagai batang di bawah harga untuk setiap periode."],["Trader memakai volume untuk menilai kekuatan pergerakan. Kenaikan harga yang disertai volume tinggi menunjukkan banyak pihak ikut bertransaksi, sedangkan kenaikan dengan volume rendah lebih mudah berbalik. Volume juga menjadi petunjuk ",["likuiditas","liquidity"],", meski tidak sama persis."],["Perlu diingat, volume futures dan spot dihitung terpisah, dan volume futures sering jauh lebih besar karena ",["leverage","leverage"],". Volume yang dilaporkan exchange juga bisa dipengaruhi ",["wash trading","wash-trading"],", jadi bandingkan beberapa sumber dan lihat juga kedalaman order book."]],"example":"Misalkan dalam 24 jam pasangan ETH/USDT di sebuah exchange mencatat 40.000 ETH berpindah tangan dengan harga rata-rata 3.000 USDT. Volume 24 jamnya adalah 40.000 x 3.000 = 120 juta USDT. Jika keesokan harinya harga naik 6% tetapi volumenya turun menjadi 15.000 ETH, kenaikan itu terjadi dengan partisipasi yang jauh lebih sedikit, sehingga Anda perlu lebih berhati-hati menilai apakah tren tersebut kuat.","mistakes":["Menganggap volume tinggi pasti berarti harga akan naik, padahal volume tinggi juga terjadi saat aksi jual besar.","Membandingkan volume spot dengan volume futures seolah-olah keduanya sama.","Percaya begitu saja pada volume exchange kecil yang tidak sebanding dengan kedalaman order book-nya."],"faq":[{"q":"Apa bedanya volume trading dan market cap?","a":"Market cap adalah nilai total suplai beredar pada harga saat ini, sedangkan volume adalah nilai yang diperdagangkan dalam satu periode. Market cap mengukur ukuran, volume mengukur aktivitas."},{"q":"Apakah volume 24 jam bisa dipalsukan?","a":"Bisa, lewat wash trading, yaitu jual-beli dengan diri sendiri untuk menggelembungkan angka. Karena itu, bandingkan volume dengan kedalaman order book dan data dari beberapa sumber."}],"title":"Apa itu volume trading kripto? Arti dan cara membacanya","description":"Pelajari arti volume trading di kripto, cara membaca volume di grafik, dan kenapa volume tinggi tidak selalu berarti pasar sehat.","related":[["liquidity","Likuiditas (liquidity)","Likuiditas adalah seberapa mudah dan cepat sebuah aset kripto bisa dibeli atau dijual dalam jumlah besar tanpa menggeser harganya secara signifikan."],["market-capitalization","Market capitalization (kapitalisasi pasar)","Market capitalization atau kapitalisasi pasar adalah nilai total sebuah aset kripto yang beredar, dihitung dari harga saat ini dikali jumlah suplai yang beredar."],["open-interest","Open interest (OI)","Open interest adalah total nilai atau jumlah kontrak futures dan opsi yang masih terbuka dan belum ditutup atau diselesaikan pada suatu waktu."],["wash-trading","Wash trading","Wash trading adalah praktik membeli dan menjual aset kepada diri sendiri atau pihak yang bekerja sama untuk menciptakan kesan volume dan aktivitas pasar yang sebenarnya tidak ada."]],"lesson":null,"coin":null,"tool":"/coins","cta":false},"position-sizing":{"slug":"position-sizing","cat":"trading","en":"Position sizing","contentLocale":"id","term":"Position sizing (ukuran posisi)","aka":["ukuran posisi","money management","manajemen posisi"],"short":"Position sizing adalah cara menentukan berapa besar modal yang dipakai untuk satu trade, berdasarkan seberapa banyak kerugian yang siap Anda tanggung jika stop loss tersentuh.","body":[["Prinsip dasarnya: tentukan dulu risiko per trade, misalnya 1% dari total akun, lalu hitung ukuran posisi dari jarak antara harga masuk dan ",["stop loss","stop-loss"],". Dengan cara ini, satu kerugian tidak pernah merusak akun Anda, seberapa pun lebarnya stop loss."],["Rumus sederhananya: ukuran posisi = jumlah risiko dibagi jarak stop loss dalam persen. ",["Leverage","leverage"]," tidak mengubah risiko Anda jika ukuran posisi sudah dihitung dengan benar; leverage hanya mengubah berapa margin yang dikunci. Namun leverage tinggi mendekatkan ",["harga likuidasi","liquidation-price"],", jadi pastikan ",["likuidasi","liquidation"]," berada jauh di luar stop loss Anda."],"Banyak trader pemula fokus mencari entry sempurna, padahal yang paling menentukan bertahan lama adalah ukuran posisi yang konsisten."],"example":["Akun Anda 5.000 ",["USDT","usdt"]," dan Anda memutuskan risiko maksimal 1% per trade, yaitu 50 USDT. Anda ingin long ",["BTC","bitcoin"]," di 62.000 dengan stop loss di 60.760, jaraknya 2%. Ukuran posisi = 50 dibagi 2% = 2.500 USDT, atau sekitar 0,0403 BTC. Dengan leverage 5x, margin yang dikunci hanya 500 USDT, tetapi kerugian jika stop loss tersentuh tetap sekitar 50 USDT ditambah biaya. Jika stop Anda 5%, ukuran posisi turun menjadi 1.000 USDT."],"mistakes":["Menentukan ukuran posisi dari feeling atau dari sisa saldo, bukan dari jarak stop loss.","Mengira leverage tinggi otomatis berarti risiko tinggi, lalu mengabaikan ukuran posisi yang sebenarnya.","Menaikkan ukuran posisi setelah rugi untuk membalas kerugian."],"faq":[{"q":"Berapa persen risiko per trade yang wajar?","a":"Banyak trader memakai 0,5-2% dari akun per trade. Angka pastinya tergantung gaya Anda, tetapi yang penting adalah konsisten dan tahan terhadap rangkaian kekalahan."},{"q":"Apakah position sizing berlaku untuk trading spot?","a":"Ya. Di spot pun Anda bisa menentukan stop loss dan menghitung berapa banyak koin yang dibeli agar kerugian maksimal sesuai rencana."}],"title":"Apa itu position sizing? Cara hitung ukuran posisi","description":"Pelajari position sizing di trading kripto: rumus ukuran posisi dari risiko dan stop loss, plus hubungannya dengan leverage.","related":[["risk-reward-ratio","Rasio risk-reward (risk-reward ratio)","Rasio risk-reward adalah perbandingan antara potensi kerugian sebuah trade (jarak ke stop loss) dan potensi keuntungannya (jarak ke take profit), misalnya 1:2."],["stop-loss","Stop loss","Stop loss adalah order otomatis untuk menutup posisi ketika harga bergerak melawan Anda sampai level tertentu, agar kerugian dibatasi sesuai rencana."],["leverage","Leverage (daya ungkit)","Leverage adalah fitur yang memungkinkan Anda membuka posisi lebih besar dari modal yang disetor, misalnya 10x berarti margin 100 USDT mengendalikan posisi senilai 1.000 USDT."],["liquidation","Likuidasi (liquidation)","Likuidasi adalah penutupan paksa posisi leverage oleh exchange ketika margin yang tersisa tidak lagi cukup untuk memenuhi maintenance margin, sehingga sebagian besar atau seluruh margin posisi itu hilang."]],"lesson":{"id":"E16","slug":"position-sizing-basics","ep":16,"title":"Tentukan berapa banyak kerugian sebelum memutuskan berapa banyak yang dibeli"},"coin":null,"tool":null,"cta":false},"funding-rate":{"slug":"funding-rate","cat":"derivatives","en":"Funding rate","contentLocale":"id","term":"Funding rate","aka":["biaya funding","funding fee","tingkat pendanaan"],"short":"Funding rate adalah pembayaran berkala antara trader posisi long dan short di kontrak perpetual yang menjaga harga kontrak tetap dekat dengan harga spot.","body":[["Jika funding rate positif, posisi long membayar posisi short. Jika negatif, short membayar long. Exchange tidak mengambil pembayaran ini; dananya berpindah langsung antar-trader. Rate dihitung dari selisih harga ",["perpetual","perpetual-futures"]," terhadap ",["harga indeks","index-price"],", ditambah komponen suku bunga, dengan batas atas dan bawah yang ditentukan exchange."],"Pembayaran hanya terjadi jika Anda memegang posisi pada saat settlement funding. Intervalnya umumnya setiap 8 jam, tetapi beberapa exchange dan pasangan memakai 1, 2, atau 4 jam, dan interval bisa diubah saat pasar ekstrem. Cek halaman spesifikasi kontrak exchange Anda.",["Funding rate juga dibaca sebagai indikator sentimen. Funding positif tinggi menunjukkan banyak trader long dengan ",["leverage","leverage"],", kondisi yang bisa memicu long squeeze jika harga berbalik. Funding sangat negatif menunjukkan posisi short ramai."]],"example":["Misalkan Anda memegang long SOL senilai 8.000 ",["USDT","usdt"]," dan funding rate 0,03% per 8 jam. Setiap settlement, Anda membayar 8.000 x 0,03% = 2,4 USDT. Dalam sehari ada tiga settlement, jadi 7,2 USDT per hari, atau sekitar 216 USDT dalam 30 hari jika rate tetap. Dengan margin 1.000 USDT, biaya itu setara 21,6% margin Anda per bulan, sehingga harga perlu naik cukup jauh hanya untuk menutup biaya funding."],"mistakes":["Menghitung funding dari margin, padahal dihitung dari nilai posisi.","Mengira funding negatif pasti berarti harga akan naik.","Membuka posisi beberapa menit sebelum settlement tanpa sadar akan langsung membayar funding."],"faq":[{"q":"Apakah funding rate negatif itu bullish?","a":"Tidak otomatis. Funding negatif berarti posisi short sedang ramai dan membayar long; ini bisa memicu short squeeze, tetapi harga juga bisa terus turun."},{"q":"Siapa yang menerima pembayaran funding?","a":"Trader di sisi berlawanan. Jika rate positif, pemegang long membayar pemegang short, dan exchange tidak mengambil bagian dari pembayaran ini."},{"q":"Apakah funding dibayar jika saya menutup posisi sebelum settlement?","a":"Tidak. Funding hanya dikenakan pada posisi yang masih terbuka tepat saat waktu settlement funding."}],"title":"Apa itu funding rate? Arti dan cara hitungnya","description":"Pahami funding rate di kontrak perpetual: siapa membayar siapa, cara menghitung biayanya, interval settlement, dan arti sentimennya.","related":[["perpetual-futures","Kontrak berjangka perpetual (perpetual futures)","Kontrak berjangka perpetual adalah kontrak futures tanpa tanggal jatuh tempo yang harganya dijaga tetap dekat dengan harga spot melalui pembayaran funding rate berkala antara posisi long dan short."],["funding-rate-arbitrage","Arbitrase funding rate (funding rate arbitrage)","Arbitrase funding rate adalah strategi netral pasar yang membeli aset di spot dan membuka short dengan ukuran sama di perpetual, sehingga risiko harga saling meniadakan dan keuntungan berasal dari pembayaran funding."],["mark-price","Mark price (harga tanda)","Mark price adalah harga acuan yang dihitung exchange dari harga indeks beberapa exchange spot dan basis kontrak, dipakai untuk menghitung unrealized PnL dan memicu likuidasi pada kontrak futures."],["index-price","Harga indeks (index price)","Harga indeks adalah rata-rata tertimbang harga spot sebuah aset dari beberapa exchange besar, dipakai exchange sebagai acuan untuk mark price, funding rate, dan settlement kontrak futures."],["open-interest","Open interest (OI)","Open interest adalah total nilai atau jumlah kontrak futures dan opsi yang masih terbuka dan belum ditutup atau diselesaikan pada suatu waktu."]],"lesson":{"id":"E24","slug":"funding-fees-final","ep":24,"title":"Harga datar, saldo turun? Selesaikan level terakhir dengan mengingat biaya"},"coin":null,"tool":"/funding-rates","cta":true},"defi":{"slug":"defi","cat":"defi","en":"DeFi (decentralized finance)","contentLocale":"id","term":"DeFi (keuangan terdesentralisasi)","aka":["decentralized finance","keuangan terdesentralisasi","DeFi"],"short":"DeFi adalah layanan keuangan yang berjalan di atas smart contract di blockchain, seperti swap, pinjam-meminjam, dan staking, tanpa perantara seperti bank atau exchange terpusat.","body":[["Di layanan keuangan biasa, ada lembaga yang memegang dana dan memproses transaksi. Di DeFi, aturan ditulis dalam ",["smart contract","smart-contract"]," yang berjalan otomatis. Anda menghubungkan ",["dompet non-kustodian","non-custodial-wallet"],", menandatangani transaksi, dan kontrak langsung menjalankannya. Contoh terkenal adalah Uniswap untuk swap, Aave untuk pinjam-meminjam, dan Lido untuk ",["liquid staking","liquid-staking"],"."],["Kelebihan DeFi adalah akses terbuka 24 jam, transparansi karena semua transaksi tercatat di ",["blockchain","blockchain"],", dan komposabilitas, yaitu satu protokol bisa memakai protokol lain seperti balok Lego."],["Risikonya juga khas. Bug smart contract bisa dieksploitasi, harga oracle bisa dimanipulasi, posisi pinjaman bisa terkena ",["likuidasi","liquidation"],", dan Anda sendiri yang bertanggung jawab atas kunci serta approval. Tidak ada layanan pelanggan yang bisa membatalkan transaksi yang salah."]],"example":["Misalnya Anda memegang 1 ",["ETH","ethereum"]," dan butuh stablecoin tanpa menjual ETH. Anda menyetor 1 ETH ke protokol lending sebagai jaminan saat harga ETH 3.000 USDT, lalu meminjam 1.200 USDC, yaitu 40% dari nilai jaminan. Kontrak mencatat posisi Anda dan membebankan bunga pinjaman yang berubah-ubah. Jika harga ETH turun cukup dalam hingga melewati ambang likuidasi protokol, sebagian ETH Anda akan dijual otomatis untuk melunasi pinjaman."],"mistakes":["Mengira DeFi bebas risiko karena tidak ada perantara.","Mengejar imbal hasil tertinggi tanpa memahami dari mana imbal hasil itu berasal.","Memakai protokol baru yang belum teruji dengan seluruh dana sekaligus."],"faq":[{"q":"Apa beda DeFi dan CeFi?","a":"CeFi seperti exchange terpusat memegang dana Anda dan menjalankan layanan di sistemnya sendiri. DeFi berjalan di smart contract, dan Anda memegang kunci dompet sendiri."},{"q":"Apakah DeFi legal di Indonesia?","a":"Aturan kripto berbeda di tiap negara dan terus berkembang. Di Indonesia, pengawasan aset kripto berpindah dari Bappebti ke OJK sejak Januari 2025, tetapi protokol DeFi umumnya tidak berbentuk perusahaan berizin, jadi perlindungan konsumennya terbatas."}],"title":"Apa itu DeFi? Arti keuangan terdesentralisasi","description":"Pelajari arti DeFi, contoh protokol seperti Uniswap dan Aave, cara kerjanya, serta risiko utama yang perlu Anda pahami.","related":[["dex","DEX (decentralized exchange)","DEX adalah exchange kripto yang berjalan di smart contract, di mana Anda bertransaksi langsung dari dompet sendiri tanpa menyetor dana ke perusahaan perantara."],["smart-contract","Smart contract","Smart contract adalah program yang disimpan dan dijalankan di blockchain, yang otomatis mengeksekusi aturan tertentu ketika syaratnya terpenuhi, tanpa perlu perantara."],["total-value-locked","TVL (total value locked)","TVL adalah total nilai aset kripto yang disetor ke sebuah protokol DeFi atau blockchain, dihitung dalam dolar AS, dan sering dipakai sebagai ukuran kasar seberapa besar sebuah protokol dipakai."],["defi-lending","DeFi lending (pinjam-meminjam DeFi)","DeFi lending adalah layanan pinjam-meminjam kripto lewat smart contract, di mana pemberi pinjaman mendapat bunga dan peminjam harus menyetor jaminan melebihi nilai pinjamannya."],["liquidity-pool","Liquidity pool (kolam likuiditas)","Liquidity pool adalah kumpulan token yang dikunci dalam smart contract, biasanya berpasangan, untuk melayani swap di DEX atau pinjaman di protokol DeFi."]],"lesson":null,"coin":{"slug":"aave","name":"Aave","symbol":"AAVE"},"tool":null,"cta":false},"cross-chain-bridge":{"slug":"cross-chain-bridge","cat":"defi","en":"Cross-chain bridge","contentLocale":"id","term":"Cross-chain bridge (jembatan antar-chain)","aka":["bridge","jembatan kripto","bridging","jembatan lintas chain"],"short":"Cross-chain bridge adalah protokol yang memindahkan aset atau data dari satu blockchain ke blockchain lain, misalnya memindahkan USDC dari Ethereum ke Arbitrum.","body":[[["Blockchain","blockchain"]," tidak bisa saling membaca secara langsung. Banyak bridge memakai model kunci dan cetak: aset dikunci di kontrak pada chain asal, lalu versi wrapped dicetak di chain tujuan. Model lain memakai ",["pool likuiditas","liquidity-pool"]," di kedua sisi, atau burn and mint untuk token yang diterbitkan resmi di banyak chain, seperti CCTP milik Circle untuk ",["USDC","usdc"],"."],["Bridge bawaan ",["layer 2","layer-2"],", misalnya bridge resmi Arbitrum atau Optimism, biasanya paling terpercaya tetapi penarikan kembali ke ",["Ethereum","ethereum"]," bisa memakan waktu sekitar tujuh hari karena masa tantangan. Bridge pihak ketiga lebih cepat tetapi menambah asumsi kepercayaan."],"Bridge adalah salah satu target peretasan terbesar dalam sejarah kripto karena menampung dana besar di satu kontrak. Gunakan bridge yang sudah dikenal, buka situs dari sumber resmi, uji dengan jumlah kecil, dan pastikan token yang diterima adalah versi yang didukung di chain tujuan. Untuk perpindahan antar jaringan yang didukung exchange, menyetor lalu menarik lewat exchange kadang lebih sederhana."],"example":["Anda ingin memindahkan 1.000 USDC dari Ethereum ke Arbitrum untuk memakai ",["DEX","dex"]," di sana. Anda membayar biaya gas di Ethereum, misalnya setara 4 USDC, dan biaya bridge contoh 1 USDC. Setelah beberapa menit, sekitar 999 USDC tiba di alamat yang sama di Arbitrum, sementara biaya gas 4 USDC dibayar dalam ETH dari saldo Anda. Anda juga menyisakan sedikit ETH di Arbitrum untuk membayar gas transaksi berikutnya."],"mistakes":["Memakai situs bridge dari tautan iklan atau DM tanpa memeriksa domain resminya.","Tiba di chain tujuan tanpa memiliki koin native untuk biaya gas.","Menerima versi wrapped token yang tidak didukung exchange atau protokol tujuan."],"faq":[{"q":"Apakah bridge kripto aman?","a":"Bridge membawa risiko smart contract dan risiko operator. Bridge resmi dan yang sudah lama teruji umumnya lebih dapat diandalkan, tetapi tetap sebaiknya diuji dengan jumlah kecil terlebih dahulu."},{"q":"Berapa lama proses bridge?","a":"Tergantung bridge dan jaringannya, bisa hitungan menit. Penarikan dari optimistic rollup ke Ethereum lewat bridge resmi bisa memakan sekitar tujuh hari."}],"title":"Apa itu cross-chain bridge? Cara kerja dan risikonya","description":"Pelajari arti cross-chain bridge, model kunci dan cetak, waktu proses, serta cara mengurangi risiko saat memindahkan aset antar chain.","related":[["wrapped-token","Wrapped token (token terbungkus)","Wrapped token adalah token yang mewakili aset lain dengan perbandingan 1:1, misalnya WBTC yang mewakili BTC di Ethereum, sehingga aset itu bisa dipakai di jaringan atau aplikasi yang tidak mendukungnya secara langsung."],["layer-2","Layer 2 (L2)","Layer 2 (L2) adalah jaringan yang dibangun di atas blockchain layer 1, memproses transaksi di luar jaringan utama lalu menyetor ringkasannya ke L1 agar lebih cepat dan murah."],["blockchain-network","Jaringan deposit (pilihan chain)","Jaringan deposit adalah blockchain yang Anda pilih untuk mengirim atau menerima sebuah aset, misalnya USDT lewat Tron, Ethereum, atau BNB Smart Chain, dan pilihan ini harus sama di sisi pengirim dan penerima."],["smart-contract","Smart contract","Smart contract adalah program yang disimpan dan dijalankan di blockchain, yang otomatis mengeksekusi aturan tertentu ketika syaratnya terpenuhi, tanpa perlu perantara."]],"lesson":{"id":"E09","slug":"pre-transfer-checklist","ep":9,"title":"Sebelum transfer: jangan tebak-tebak hal-hal ini"},"coin":null,"tool":null,"cta":false},"stablecoin":{"slug":"stablecoin","cat":"stablecoins","en":"Stablecoin","contentLocale":"id","term":"Stablecoin","aka":["koin stabil","stable coin","dolar kripto"],"short":"Stablecoin adalah aset kripto yang dirancang menjaga nilai stabil terhadap aset acuan, biasanya 1 dolar AS, seperti USDT dan USDC, sehingga dipakai sebagai alat tukar dan tempat parkir dana di pasar kripto.","body":[["Ada beberapa jenis stablecoin. Stablecoin berbasis fiat seperti ",["USDT","usdt"]," dari Tether dan ",["USDC","usdc"]," dari Circle didukung cadangan kas dan surat utang jangka pendek. ",["Stablecoin berjaminan kripto","crypto-backed-stablecoin"]," seperti DAI atau USDS dicetak dengan jaminan kripto berlebih. Ada juga ",["dolar sintetis","synthetic-dollar"]," seperti USDe yang menjaga nilai lewat posisi ",["lindung nilai","hedging"]," di pasar derivatif."],["Di exchange, stablecoin menjadi mata uang utama: sebagian besar pasangan spot dan ",["kontrak futures","futures-contract"]," memakai USDT atau USDC. Trader memakainya untuk keluar sementara dari aset volatil, transfer antar exchange, dan P2P. Di exchange Indonesia, stablecoin juga diperdagangkan terhadap rupiah, sehingga kursnya bisa sedikit berbeda dari kurs dolar resmi."],"Stabil bukan berarti tanpa risiko. Stablecoin bisa depeg jika cadangan diragukan, ada masalah bank atau kustodian, atau mekanisme jaminannya gagal. Penerbit fiat-backed juga bisa membekukan alamat tertentu. Regulasinya berkembang, misalnya aturan stablecoin MiCA di Uni Eropa berlaku sejak 30 Juni 2024."],"example":"Misalnya Anda memegang 0,1 BTC senilai 6.000 USDT dan khawatir volatilitas jangka pendek. Anda menjualnya ke USDT dengan fee taker contoh 0,1%, sehingga menerima 5.994 USDT. Seminggu kemudian, saldo Anda tetap sekitar 5.994 USDT apa pun pergerakan BTC. Jika Anda lalu menjual USDT ke rupiah di kurs contoh 16.000 rupiah per USDT, Anda menerima sekitar 95,9 juta rupiah sebelum biaya penarikan.","mistakes":["Menganggap semua stablecoin memiliki jaminan dan risiko yang sama.","Mengabaikan jaringan saat mengirim stablecoin, misalnya mengirim USDT TRC20 ke alamat ERC20.","Mengira imbal hasil tinggi dari stablecoin di platform tidak dikenal itu bebas risiko karena asetnya stabil."],"faq":[{"q":"Apakah stablecoin selalu bernilai 1 dolar?","a":"Dirancang untuk mendekati 1 dolar, tetapi harga pasarnya bisa sedikit menyimpang dan dalam kondisi buruk bisa depeg cukup jauh."},{"q":"Apa stablecoin yang paling banyak dipakai?","a":"USDT dari Tether dan USDC dari Circle adalah dua stablecoin dolar terbesar dan paling banyak tersedia di exchange."}],"title":"Apa itu stablecoin? Arti, jenis, dan risikonya","description":"Pelajari arti stablecoin, jenis berbasis fiat, berjaminan kripto, dan sintetis, kegunaannya di exchange, serta risiko depeg.","related":[["usdt","USDT (Tether)","USDT adalah stablecoin yang diterbitkan Tether dan dirancang bernilai 1 dolar AS, serta menjadi stablecoin dengan peredaran terbesar dan pasangan perdagangan paling umum di exchange kripto."],["usdc","USDC (USD Coin)","USDC adalah stablecoin yang diterbitkan Circle dan dirancang bernilai 1 dolar AS, didukung cadangan kas dan surat utang pemerintah AS jangka pendek, serta banyak dipakai di DeFi dan exchange."],["depeg","Depeg","Depeg adalah kondisi ketika harga stablecoin atau aset yang dipatok menyimpang cukup jauh dari nilai patokannya, misalnya USDT atau USDC diperdagangkan jauh di bawah 1 dolar AS."],["crypto-backed-stablecoin","Stablecoin berjaminan kripto (crypto-backed stablecoin)","Stablecoin berjaminan kripto adalah stablecoin yang dicetak dengan mengunci aset kripto seperti ETH sebagai jaminan dengan nilai lebih besar daripada stablecoin yang diterbitkan."],["synthetic-dollar","Dolar sintetis (synthetic dollar)","Dolar sintetis adalah token bernilai sekitar 1 dolar yang dijaga lewat posisi delta-netral, yaitu memegang aset kripto sekaligus membuka posisi short dengan ukuran sama di kontrak berjangka perpetual."]],"lesson":{"id":"E02","slug":"is-usdt-a-dollar","ep":2,"title":"Apakah USDT itu dolar? Mengapa sering muncul saat beli kripto?"},"coin":{"slug":"tether","name":"Tether","symbol":"USDT"},"tool":null,"cta":false}});
